__device__ __forceinline__ float block_reduce_max(float val, float* smem) {
    int tid = (int)threadIdx.x;
    smem[tid] = val;
    __syncthreads();
    for (int offset = (int)blockDim.x >> 1; offset > 0; offset >>= 1) {
